  for r in (select * from json_table(l_payload,'$[*]' columns (
    eco_code varchar2(1200) path '$.eco_code',
    description clob path '$.description' null on empty))) loop
    merge into orac_chess.chess_eco_code t
    using (select r.eco_code eco_code,r.description description from dual) s
    on (t.eco_code=s.eco_code)
    when matched then update set t.description=s.description
      where (t.description is null and s.description is not null)
        or (t.description is not null and s.description is null)
        or dbms_lob.compare(t.description,s.description)<>0
    when not matched then insert (eco_code,description)
      values (s.eco_code,s.description);
  end loop;
  dbms_lob.freetemporary(l_payload);
